{"path": "/tmp_test_check.py", "content": "import sqlparse
from sqlparse import sql

sql_stmt = 'select * from (select * from foo where bar = 1) x'
p = sqlparse.parse(sql_stmt)[0]
for t in p.tokens:
    print(repr(t))
print('---inner---')
par = [t for t in p.tokens if isinstance(t, sql.Parenthesis)][0]
for t in par.tokens:
    print(repr(t))

print('=== second case ===')
p2 = sqlparse.parse('select * from foo where bar in (select id from baz where x = 1)')[0]
def dump(tl, indent=0):
    for t in tl.tokens:
        print(' ' * indent + repr(t))
        if t.is_group:
            dump(t, indent + 2)
dump(p2)
"}

